from .ast import Program


def generate_llvm_ir(program: Program, source_name: str = "input.ocl") -> str:
    lines = [
        "; Generated by oclc 0.1",
        f'source_filename = "{source_name.replace(chr(34), "_")}"',
        "",
    ]
    for function in program.functions:
        value = function.body[0].expression.value
        lines.extend((f"define i32 @{function.name}() {{", "entry:", f"  ret i32 {value}", "}", ""))
    return "\n".join(lines)
